// deslocamento determinístico por índice (seed fixa)
const off = (i, k) => Math.sin(i * 12.9898 + k * 78.233) * 400;
tl.fromTo(items, { x: (i) => off(i, 1), y: (i) => off(i, 2), rotation: (i) => off(i, 3) / 4, opacity: 0 }, { x: 0, y: 0, rotation: 0, opacity: 1, duration: 0.7, ease: "power3.out", stagger: 0.03 }, t);

// dx/dy: distância de cada item até o centro do grupo (medida no setup)
const dx = items.map((it) => it.dataset.dx * 1 || 0), dy = items.map((it) => it.dataset.dy * 1 || 0);
tl.fromTo(items, { x: (i) => dx[i], y: (i) => dy[i], scale: 0.4, opacity: 0 }, { x: 0, y: 0, scale: 1, opacity: 1, duration: 0.7, ease: "expo.out" }, t);
